/**
 * TESTS:
 * - promptTokensMatchTransformers: the GGUF tokenizer gives the reference prompt in Qwen-Image's template the token ids
 *   of transformers' tokenizer
 * - firstLayerMatchesTransformers: the hidden states after the first decoder layer match transformers'
 *   Qwen2_5_VLDecoderLayer on the same dequantized weights
 * - hiddenStatesMatchTransformers: the final normed hidden states of all 28 layers match the reference
 *
 * The references are generated by scripts/qwen_image/text_reference.py into build/models/qwen-image/reference/ from
 * the GGUF in build/models/qwen-image/text/ (neither is in the repository); the tests skip without them.
 **/

#include <gtest/gtest.h>

#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <sstream>

#include "klartraum/computegraph/computegraph.hpp"
#include "klartraum/diffusion/qwen_text_encoder.hpp"
#include "klartraum/headless_frontend.hpp"

using namespace klartraum;

namespace {

const std::string kModel = "./build/models/qwen-image/text/Qwen2.5-VL-7B-Instruct-Q4_K_M.gguf";
const std::string kReference = "./build/models/qwen-image/reference/";

template <typename T>
std::vector<T> readValues(const std::string& path) {
    std::ifstream file(path, std::ios::binary | std::ios::ate);
    std::vector<T> data(static_cast<size_t>(file.tellg()) / sizeof(T));
    file.seekg(0);
    file.read(reinterpret_cast<char*>(data.data()), static_cast<std::streamsize>(data.size() * sizeof(T)));
    return data;
}

std::string readText(const std::string& path) {
    std::ifstream file(path);
    std::stringstream text;
    text << file.rdbuf();
    return text.str();
}

bool referencesExist() {
    return std::filesystem::exists(kModel) && std::filesystem::exists(kReference + "text_hidden_f32.bin");
}

// Runs the encoder (all layers, or only the first @p layers) on the reference tokens and returns its hidden states.
std::vector<float> encode(uint32_t layers) {
    HeadlessFrontend frontend;
    auto& vc = frontend.getKlartraumEngine().getVulkanContext();
    const auto tokens = readValues<int32_t>(kReference + "text_tokens_i32.bin");
    auto encoder = vc.create<QwenTextEncoder>(kModel, QwenTextEncoderOptions{128, layers});
    ComputeGraph graph(vc, 1);
    graph.compileFrom(encoder);
    encoder->setTokens(tokens);
    graph.submitAndWait(vc.getGraphicsQueue(), 0);
    return encoder->readHiddenStates();
}

// Per token, the largest difference relative to the token's largest reference magnitude; returns the worst token's.
float worstRelativeError(const std::vector<float>& actual, const std::vector<float>& expected, uint32_t width) {
    EXPECT_EQ(actual.size(), expected.size());
    float worst = 0.0f;
    for (size_t token = 0; token < std::min(actual.size(), expected.size()) / width; ++token) {
        float difference = 0.0f, magnitude = 0.0f;
        for (size_t i = token * width; i < (token + 1) * width; ++i) {
            difference = std::max(difference, std::abs(actual[i] - expected[i]));
            magnitude = std::max(magnitude, std::abs(expected[i]));
        }
        worst = std::max(worst, difference / magnitude);
    }
    return worst;
}

} // namespace

TEST(QwenTextEncoderTest, promptTokensMatchTransformers) {
    if (!referencesExist())
        GTEST_SKIP() << "run scripts/qwen_image/text_reference.py first";
    const auto expected = readValues<int32_t>(kReference + "text_tokens_i32.bin");
    HeadlessFrontend frontend;
    auto& vc = frontend.getKlartraumEngine().getVulkanContext();
    auto encoder = vc.create<QwenTextEncoder>(kModel, QwenTextEncoderOptions{128, 1});
    EXPECT_EQ(encoder->promptTokens(readText(kReference + "text_prompt.txt")), expected);
}

TEST(QwenTextEncoderTest, firstLayerMatchesTransformers) {
    if (!referencesExist())
        GTEST_SKIP() << "run scripts/qwen_image/text_reference.py first";
    const auto expected = readValues<float>(kReference + "text_layer0_f32.bin");
    EXPECT_LT(worstRelativeError(encode(1), expected, 3584), 1e-3f);
}

TEST(QwenTextEncoderTest, hiddenStatesMatchTransformers) {
    if (!referencesExist())
        GTEST_SKIP() << "run scripts/qwen_image/text_reference.py first";
    const auto expected = readValues<float>(kReference + "text_hidden_f32.bin");
    EXPECT_LT(worstRelativeError(encode(0), expected, 3584), 1e-2f);
}
